############################################################ # PG Setup Code ############################################################ $rule = list_random('Left Hand Rule','Right Hand Rule'); if($envir{problemSeed}==1){$rule='Right Hand Rule';}; $f = Formula("x^3 - x^2")->reduce; Context("Fraction"); Context()->variables->are(n=>"Real"); $sum = Formula("-1/12+1/(12n^2)"); $sum10 = $sum->eval(n=>10); $sum100 = $sum->eval(n=>100); $sum1000 = $sum->eval(n=>1000); $exact = Fraction(-1,12);
